const liveSlugs = new Set(liveTools.map((tool) => tool.slug))
const browserImplementedSlugs = new Set(browserImplementedToolSlugs)

const catalogTools: PublicTool[] = catalogToolSeeds.map((tool) => {
  const slug = slugify(tool.title)
  const isImplemented = browserImplementedSlugs.has(slug)

  return {
    slug,
    title: tool.title,
    shortTitle: shortTitle(tool.title),
    description: tool.description,
    category: tool.category,
    workflow: tool.workflow,
    badge: isImplemented ? "Free" : tool.badge ?? "Planned",
    status: isImplemented ? "Live" : "Queued",
    icon: tool.icon,
    delivery: tool.delivery ?? "Browser",
    keywords: tool.keywords,
  }
})

export const publicTools: PublicTool[] = [
  ...liveTools,
  ...catalogTools.filter((tool) => !liveSlugs.has(tool.slug)),
]

